<script setup>
import {emptyTheme,templateSlots} from '../../../shared/themes.js'

import {ref,computed,watch,onMounted,onBeforeUnmount} from 'vue'
import {defaultDesign,designValue,textGroups,textLabels} from '../../../shared/siteDesign.js'
import CodeEditor from './CodeEditor.vue'
import CodeFrame from '../../../shared/CodeFrame.vue'
import MediaPicker from './MediaPicker.vue'
const props=defineProps({apiWrite:Function})
const emit=defineEmits(['dirty'])
const form=ref(null),revision=ref(''),baseline=ref(''),busy=ref(false),error=ref(''),notice=ref(''),versions=ref([]),tab=ref('content'),file=ref('html'),preview=ref(null),previewKey=ref(0),previewWidth=ref('100%'),runtimeError=ref('')
const dirty=computed(()=>form.value&&JSON.stringify(form.value)!==baseline.value)
watch(dirty,value=>emit('dirty',Boolean(value)))
const themeSlot=ref('home'),themeFile=ref('html'),themePreview=ref(null),themeError=ref(''),formChoices=ref([])
const themeDemo=computed(()=>({settings:{name:'Предпросмотр NOVA',shop_enabled:true,blog_enabled:false,menu:[]},products:[],design:{texts:form.value.texts,colors:form.value.colors,font:form.value.font,width:form.value.width,radius:form.value.radius},theme:{id:form.value.theme?.manifest.id,settings:form.value.theme?.settings||{}},route:{path:'/',search:''},context:{page:{title:'Пример страницы',content:'Текст страницы'},product:{id:1,name:'Пример товара',description:'Текст карточки',price:100,stock:1,variants:[],image_url:''}},cartSummary:{count:0,total_cents:0}}))
function addTemplate(){form.value.theme.templates[themeSlot.value]={html:'<section><h1 id="title"></h1></section>',css:'section { padding: 32px; }',js:'document.getElementById("title").textContent = NOVA.settings.name;'};themePreview.value=null}
function runTheme(){themePreview.value=JSON.parse(JSON.stringify(form.value.theme.templates[themeSlot.value]));themeError.value=''}
const visibilityLabels={announcement:'Строка над шапкой',header:'Шапка и меню',hero:'Первый экран',advantages:'Преимущества',catalog:'Каталог',footer:'Подвал',year:'Год в подвале',floating:'Плавающая карточка'}
const colorLabels={primary:'Кнопки и активные элементы',accent:'Акцент',background:'Фон сайта',text:'Основной текст',hero:'Фон первого экрана',footer:'Фон подвала'}
const sectionLabels={hero:'Первый экран',advantages:'Преимущества',catalog:'Каталог'}
const files={html:'index.html',css:'style.css',js:'script.js',global_css:'site.css'}
function accept(row){form.value=designValue(row.draft);revision.value=row.revision;baseline.value=JSON.stringify(form.value)}
async function history(){versions.value=await props.apiWrite('/api/admin/design/versions','GET')}
async function load(){if(dirty.value&&!confirm('Загрузить сохранённый черновик и заменить несохранённые изменения?'))return;busy.value=true;error.value='';try{accept(await props.apiWrite('/api/admin/design','GET'));await history()}catch(e){error.value=e.message}finally{busy.value=false}}
async function persist(){const row=await props.apiWrite('/api/admin/design','PUT',{revision:revision.value,draft:form.value});accept(row)}
async function save(publish=false){if(busy.value||!form.value)return;busy.value=true;notice.value='';error.value='';try{await persist();if(publish)accept(await props.apiWrite('/api/admin/design/publish','POST',{revision:revision.value}));notice.value=publish?'Оформление опубликовано. Обновите сайт, чтобы увидеть изменения.':'Черновик сохранён. Сайт пока не изменился.';await history()}catch(e){error.value=e.message}finally{busy.value=false}}
async function restore(id){if(dirty.value&&!confirm('Заменить текущие изменения выбранной версией?'))return;busy.value=true;error.value='';try{form.value=await props.apiWrite('/api/admin/design/versions/'+id,'GET');notice.value='Версия загружена в редактор. Сохраните черновик или опубликуйте её.'}catch(e){error.value=e.message}finally{busy.value=false}}
function run(){preview.value=JSON.parse(JSON.stringify(form.value.code));runtimeError.value='';previewKey.value++}
function move(index,delta){const order=form.value.home_order;const target=index+delta;if(target<0||target>=order.length)return;[order[index],order[target]]=[order[target],order[index]]}
function reset(){if(confirm('Вернуть стандартное оформление в редактор? Сайт изменится только после публикации.'))form.value=designValue(defaultDesign)}
function beforeUnload(event){if(dirty.value){event.preventDefault();event.returnValue=''}}
onMounted(()=>{addEventListener('beforeunload',beforeUnload);load();props.apiWrite('/api/admin/forms','GET').then(data=>formChoices.value=data).catch(()=>{})});onBeforeUnmount(()=>removeEventListener('beforeunload',beforeUnload))
</script>
<template><div class="design-workspace"><div class="page-title"><div><span class="eyebrow">NOVA CMS</span><h1>Оформление и код</h1><p>Содержимое, стиль и собственные блоки сайта. Сначала черновик, затем публикация.</p></div><div class="design-buttons"><button class="row-btn" :disabled="busy" @click="load">Загрузить черновик</button><button class="primary-btn" :disabled="busy||!form" @click="save(false)">Сохранить черновик</button><button class="primary-btn" :disabled="busy||!form" @click="save(true)">Опубликовать</button></div></div><p v-if="error" class="alert" role="alert">{{error}}</p><p v-if="notice" class="design-notice" role="status">{{notice}}</p><p v-if="dirty" class="dirty-notice">Есть несохранённые изменения</p>
<template v-if="form"><nav class="editor-tabs" aria-label="Разделы оформления"><button v-for="(label,id) in {content:'Тексты',style:'Внешний вид',layout:'Разделы',code:'Редактор кода',theme:'Тема и шаблоны',history:'История'}" :key="id" :class="{active:tab===id}" @click="tab=id">{{label}}</button></nav><fieldset :disabled="busy" class="design-fields">
<div v-if="tab==='content'"><details v-for="(fields,group) in textGroups" :key="group" class="design-panel"><summary>{{group}}</summary><div class="design-grid"><label v-for="(original,key) in fields" :key="key">{{textLabels[key]||original||key}}<textarea v-model="form.texts[key]" rows="2" maxlength="5000"></textarea></label></div></details><p>Название, логотип, меню и выбор главной страницы находятся в разделе «Настройки». Товары, страницы и статьи редактируются в своих разделах.</p></div>
<div v-if="tab==='style'" class="design-panel"><div class="design-grid"><label v-for="(label,key) in colorLabels" :key="key">{{label}}<input v-model="form.colors[key]" type="color"></label><label>Шрифт<select v-model="form.font"><option v-for="font in ['Manrope','Arial','Georgia','Verdana']" :key="font">{{font}}</option></select></label><label>Ширина содержимого (px)<input v-model.number="form.width" type="number" min="900" max="1600"></label><label>Скругления (px)<input v-model.number="form.radius" type="number" min="0" max="32"></label></div><label>Адрес кнопки первого экрана<input v-model="form.hero_button_url" maxlength="2000" placeholder="/catalog#catalog"></label><h2>Иллюстрация первого экрана</h2><MediaPicker :disabled="busy" @select="form.hero_image_url=$event"/><img v-if="form.hero_image_url" :src="form.hero_image_url" class="design-image" alt="Иллюстрация"><button v-if="form.hero_image_url" class="row-btn" @click="form.hero_image_url=''">Убрать изображение</button><p>Если изображение не выбрано, используются эмодзи из раздела «Тексты».</p></div>
<div v-if="tab==='layout'" class="design-panel"><h2>Видимость элементов</h2><label v-for="(label,key) in visibilityLabels" :key="key" class="design-check"><input v-model="form.visibility[key]" type="checkbox">{{label}}</label><h2>Порядок разделов магазина</h2><div v-for="(id,index) in form.home_order" :key="id" class="design-order"><span>{{sectionLabels[id]}}</span><button class="row-btn" :disabled="index===0" @click="move(index,-1)">↑</button><button class="row-btn" :disabled="index===2" @click="move(index,1)">↓</button></div><button class="row-btn" @click="reset">Стандартное оформление</button></div>
<div v-if="tab==='code'"><div class="design-panel"><label class="design-check"><input v-model="form.code.enabled" type="checkbox">Включить собственный блок</label><label>Размещение<select v-model="form.code.placement"><option value="home">Заменить содержимое главной страницы</option><option value="site">Полная тема — содержимое всех публичных страниц</option><option value="footer">Добавить блок перед подвалом на всех страницах</option></select></label><p>HTML, CSS и JavaScript выполняются в отдельном блоке. Доступны публичные данные <code>window.NOVA.settings</code> и <code>window.NOVA.products</code>, текущий адрес <code>window.NOVA.route</code> и чтение публичного API через <code>await NOVA.request('/api/blog')</code>. Код изолирован от админки, cookie и серверных файлов. Fetch/XHR, формы и вложенные фреймы заблокированы. Файл site.css меняет стили всего сайта после публикации.</p></div><nav class="editor-tabs" aria-label="Файлы кода"><button v-for="(label,id) in files" :key="id" :class="{active:file===id}" @click="file=id">{{label}}</button></nav><CodeEditor v-model="form.code[file]" :language="files[file]" :disabled="busy" @save="save(false)"/><div class="preview-tools"><button class="primary-btn" @click="run">▶ Выполнить предпросмотр</button><label>Ширина<select v-model="previewWidth"><option value="100%">Вся ширина</option><option value="768px">Планшет</option><option value="375px">Телефон</option></select></label></div><p v-if="runtimeError" class="alert" role="alert">JavaScript: {{runtimeError}}</p><div v-if="preview" class="preview-shell"><div :style="{width:previewWidth,maxWidth:'100%'}"><CodeFrame :key="previewKey" :code="preview" :data="{settings:{name:'Предпросмотр NOVA'},products:[],route:{path:'/',search:''}}" title="Предпросмотр кода" @error="runtimeError=$event"/></div></div></div>
<div v-if="tab==='theme'"><div class="design-panel"><h2>Активная тема черновика</h2><p>Пакеты устанавливаются в разделе «Темы и шаблоны». Здесь можно изменить настройки и код перед публикацией.</p><button v-if="!form.theme" class="primary-btn" @click="form.theme=emptyTheme()">Создать свою тему в редакторе</button><template v-else><div class="design-grid"><label>ID темы<input v-model="form.theme.manifest.id" maxlength="80"></label><label>Название темы<input v-model="form.theme.manifest.name" maxlength="150"></label><label>Версия темы<input v-model="form.theme.manifest.version" maxlength="60" placeholder="1.0.0"></label></div><h2>Настройки темы</h2><div class="design-grid"><label v-for="f in form.theme.settings_schema" :key="f.id" :class="{'design-check':f.type==='checkbox'}">{{f.label}}<input v-if="f.type==='checkbox'" v-model="form.theme.settings[f.id]" type="checkbox"><input v-else-if="f.type==='color'" v-model="form.theme.settings[f.id]" type="color"><select v-else-if="f.type==='select'" v-model="form.theme.settings[f.id]"><option v-for="o in f.options" :key="o.value" :value="o.value">{{o.label}}</option></select><select v-else-if="f.type==='form'" v-model="form.theme.settings[f.id]" :aria-label="f.label"><option value="">Не выбрана</option><option v-for="choice in formChoices" :key="choice.id" :value="choice.id">{{choice.title}}{{choice.enabled?'':' (выключена)'}}</option></select><template v-else-if="f.type==='image'"><MediaPicker @select="form.theme.settings[f.id]=$event"/><img v-if="form.theme.settings[f.id]" :src="form.theme.settings[f.id]" class="design-image" alt="Изображение темы"><button class="row-btn" @click="form.theme.settings[f.id]=''">Убрать</button></template><textarea v-else v-model="form.theme.settings[f.id]" maxlength="3000" rows="3"></textarea></label></div><p v-if="!form.theme.settings_schema.length">Параметры settings_schema определяются автором в пакете темы. Можно начать с примера из библиотеки.</p><button class="row-btn" @click="form.theme=null;themePreview=null">Убрать шаблоны темы из черновика</button></template></div><template v-if="form.theme"><div class="design-panel"><h2>Шаблоны вывода</h2><label>Место шаблона<select v-model="themeSlot" aria-label="Место шаблона" @change="themePreview=null"><option v-for="(name,key) in templateSlots" :key="key" :value="key">{{name}}{{form.theme.templates[key]?' · свой код':' · стандарт CMS'}}</option></select></label><p>Если шаблона нет или его JavaScript завершился ошибкой, используется стандартный вывод. Корзина, оформление и модальные формы остаются в CMS.</p><button v-if="!form.theme.templates[themeSlot]" class="row-btn" @click="addTemplate">Добавить шаблон</button><button v-else class="row-btn" @click="delete form.theme.templates[themeSlot];themePreview=null">Использовать стандартный шаблон здесь</button></div><template v-if="form.theme.templates[themeSlot]"><nav class="editor-tabs" aria-label="Файлы шаблона"><button v-for="f in ['html','css','js']" :key="f" :class="{active:themeFile===f}" @click="themeFile=f">{{f==='html'?'index.html':f==='css'?'style.css':'script.js'}}</button></nav><CodeEditor v-model="form.theme.templates[themeSlot][themeFile]" :language="themeFile" :disabled="busy" @save="save(false)"/><p>До 50 000 символов на файл шаблона. HTML-обработчики onclick и теги script не исполняются: пишите поведение в script.js.</p><button class="primary-btn" @click="runTheme">Предпросмотр шаблона</button><p>В предпросмотре API, корзина и отправка форм отключены. Проверяйте действия на тестовом сайте после публикации.</p><p v-if="themeError" class="alert" role="alert">{{themeError}}</p><CodeFrame v-if="themePreview" :key="JSON.stringify(themePreview)" :code="themePreview" :data="themeDemo" title="Предпросмотр редактируемого шаблона" @error="themeError=$event"/></template></template></div>
<div v-if="tab==='history'" class="design-panel"><h2>Последние 30 версий</h2><p>Сохраняется состояние до изменения. Восстановление загружает выбранную версию в редактор.</p><div v-for="item in versions" :key="item.id" class="design-order"><span>{{new Date(item.created_at).toLocaleString('ru-RU')}} · {{item.action==='before-publish'?'До публикации':item.action==='before-theme'?'До применения темы':'До сохранения'}}</span><button class="row-btn" @click="restore(item.id)">Восстановить в редактор</button></div><p v-if="!versions.length">История появится после первого сохранения.</p></div>
</fieldset></template></div></template>
<style scoped>.design-buttons,.preview-tools,.design-order{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.design-fields{border:0;padding:0;margin:0;min-width:0}.design-panel{padding:24px;background:white;border:1px solid #dce6e0;border-radius:12px;margin-bottom:20px}.design-panel summary{font-weight:800;cursor:pointer}.design-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(260px,100%),1fr));gap:20px;margin-top:20px}label{display:grid;gap:8px;font-size:13px;font-weight:700}.design-grid input,.design-grid textarea,select{max-width:100%;min-width:0;border:1px solid #cddbd2;border-radius:7px;padding:10px;font:inherit}.design-grid input[type=color]{width:100%;height:48px;padding:4px}.design-check{display:flex;align-items:center;margin:14px 0;gap:10px}.design-image{display:block;max-width:280px;max-height:160px;margin:15px 0}.design-order{padding:12px 0;border-bottom:1px solid #e6ece8}.design-order>span{flex:1;min-width:160px}p{line-height:1.7;color:#617469;font-size:13px}.design-notice{color:#25714c}.dirty-notice{color:#9c5d13}.preview-tools{margin:20px 0}.preview-shell{overflow:auto;background:#e5ebe6;padding:16px}.preview-shell>div{margin:auto;background:white;min-width:0}h2{font-size:19px}.editor-tabs button{cursor:pointer}</style>
